```

把输出的 URL 发给我，看看里面的 `redirect_uri` 参数是什么。

容器里没有 sqlite3，用 node 执行：

```bash
docker exec iMail node -e "
const db = require('./src/db');
const oneMonthAgo = (Math.floor(Date.now()/1000) - 30*24*3600) * 1000;
const {changes} = db.prepare('UPDATE emails SET read = 1 WHERE read = 0 AND deleted = 0 AND (raw_date = 0 OR raw_date IS NULL OR raw_date < ?)').run(oneMonthAgo);
console.log('已标记:', changes);
"
```

BusyBox wget 不支持 cookie，用 node 直接调：

```bash
docker exec iMail node -e "
const http = require('http');
function req(opts, body, cb) {
  const r = http.request(opts, res => {
    let d = '';
    res.on('data', c => d += c);
    res.on('end', () => cb(res.headers, d));
  });
  if (body) r.write(body);
  r.end();
}
const loginBody = JSON.stringify({username:'admin',password:'890214'});
req({host:'localhost',port:3000,path:'/api/auth/login',method:'POST',headers:{'Content-Type':'application/json','Content-Length':loginBody.length}}, loginBody, (headers, body) => {
  const cookie = headers['set-cookie']?.[0]?.split(';')[0];
  console.log('login:', body);
  req({host:'localhost',port:3000,path:'/api/emails/sync/9b5734d5-4dbb-43fe-afdc-07286d11776d',method:'POST',headers:{Cookie:cookie}}, null, (h, b) => {
    console.log('sync:', b);
  });
});
"
```

添加后再触发同步，看同步结果：

```bash
docker exec iMail node -e "
const http = require('http');
function req(opts, body, cb) {
  const r = http.request(opts, res => {
    let d = '';
    res.on('data', c => d += c);
    res.on('end', () => cb(res.headers, d));
  });
  if (body) r.write(body);
  r.end();
}
const loginBody = JSON.stringify({username:'admin',password:'890214'});
req({host:'localhost',port:3000,path:'/api/auth/login',method:'POST',headers:{'Content-Type':'application/json','Content-Length':loginBody.length}}, loginBody, (headers, body) => {
  const cookie = headers['set-cookie']?.[0]?.split(';')[0];
  req({host:'localhost',port:3000,path:'/api/accounts',method:'GET',headers:{Cookie:cookie}}, null, (h, b) => {
    const accounts = JSON.parse(b).filter(a => a.type === 'outlook');
    console.log('Outlook账号:', accounts.map(a => a.email + ' ' + a.id));
  });
});
"
```

先看新添加的账号 id，再同步。

单账号还跳，说明 db 里这个账号的邮件 `raw_date` 有问题。检查：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const rows=db.prepare('SELECT uid,date,raw_date FROM emails WHERE account_id=? ORDER BY raw_date DESC LIMIT 5').all('ca250226-xxxx');
console.log(rows.map(r=>({uid:r.uid,date:r.date,raw_date:new Date(r.raw_date).toLocaleDateString()})))
"
```

把 `ca250226` 换成完整 id，同时跑：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const id=db.prepare('SELECT id FROM accounts').all().find(r=>r.id.startsWith('ca250226')).id;
const rows=db.prepare('SELECT raw_date,date FROM emails WHERE account_id=? ORDER BY raw_date ASC LIMIT 3').all(id);
const rows2=db.prepare('SELECT raw_date,date FROM emails WHERE account_id=? ORDER BY raw_date DESC LIMIT 3').all(id);
console.log('最老3封:',rows.map(r=>new Date(r.raw_date).toLocaleDateString()));
console.log('最新3封:',rows2.map(r=>new Date(r.raw_date).toLocaleDateString()));
const zero=db.prepare('SELECT COUNT(*) as n FROM emails WHERE account_id=? AND (raw_date=0 OR raw_date IS NULL)').get(id);
console.log('raw_date=0的数量:',zero.n);
"
```

把结果发给我。

CSS 本身没问题，不会影响邮件样式。

**"只有文字没有效果"** 说明邮件 body 里的 HTML 样式丢失了。原因是 **purge 把超半年的邮件删了，这些邮件重新从 IMAP 同步时，body 存的是纯文本而不是 HTML**。

检查一封有问题的邮件：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const r=db.prepare('SELECT id,subject,body FROM emails ORDER BY raw_date DESC LIMIT 1').get();
console.log('subject:',r.subject);
console.log('body前100:',r.body?.slice(0,100));
console.log('是否HTML:',r.body?.includes('<'));
"
```

把结果发给我。

db 里 `ca250226` 账号最老就是 1/9/2026，415 封加载完就是"已加载全部"，这是正确的。

问题是：**purge 已经把 1/9 之前的邮件删了**（之前的半年 purge 执行过），所以 db 里确实没有更早的数据了。

需要重新从 IMAP 拉取历史邮件列表（只存列表不存 body）。

确认一下：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const id=db.prepare('SELECT id FROM accounts').all().find(r=>r.id.startsWith('ca250226')).id;
const r=db.prepare('SELECT COUNT(*) as n, MIN(raw_date) as oldest FROM emails WHERE account_id=? AND deleted=0').get(id);
console.log('总数:',r.n,'最老:',new Date(r.oldest).toLocaleDateString());
const inDeleted=db.prepare('SELECT COUNT(*) as n FROM deleted_uids WHERE account_id=?').get(id);
console.log('deleted_uids:',inDeleted.n);
"
```

如果 `deleted_uids` 数量很多，说明 purge 把旧邮件 uid 记录进去了，导致重新同步时跳过这些邮件。

**需要清空 deleted_uids 让历史邮件重新同步进来：**

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const {changes}=db.prepare('DELETE FROM deleted_uids').run();
console.log('清空 deleted_uids:',changes,'条');
"
```

清空后手动点同步，历史邮件会重新拉取（超3月只存列表标已读）。把结果发给我确认。

清空了 2646 条 deleted_uids，现在手动点同步按钮，历史邮件会重新拉取进来（超3月只存列表标已读，不存 body）。

同步完成后再确认：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const id=db.prepare('SELECT id FROM accounts').all().find(r=>r.id.startsWith('ca250226')).id;
const r=db.prepare('SELECT COUNT(*) as n, MIN(raw_date) as oldest FROM emails WHERE account_id=? AND deleted=0').get(id);
console.log('总数:',r.n,'最老:',new Date(r.oldest).toLocaleDateString());
"
```

如果总数增加、最老日期变早，说明历史邮件已经拉回来了。

同步后确认 db 数据：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const id=db.prepare('SELECT id FROM accounts').all().find(r=>r.id.startsWith('ca250226')).id;
const r=db.prepare('SELECT COUNT(*) as n, MIN(raw_date) as oldest FROM emails WHERE account_id=? AND deleted=0').get(id);
console.log('总数:',r.n,'最老:',new Date(r.oldest).toLocaleDateString());
"
```

如果总数还是 415，说明同步没有拉到更早的邮件。原因是 IMAP 同步只拉最近 200 封（`Math.max(1, total - 199)`），不会拉全量历史。

看一下这个账号是什么类型：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const r=db.prepare('SELECT id,email,type FROM accounts').all().find(r=>r.id.startsWith('ca250226'));
console.log(r);
"
```

看日志确认同步实际执行情况：

```bash
docker logs iMail 2>&1 | tail -30
```

同时确认 db 数据：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const id=db.prepare('SELECT id FROM accounts').all().find(r=>r.id.startsWith('ca250226')).id;
const r=db.prepare('SELECT COUNT(*) as n, MIN(raw_date) as oldest FROM emails WHERE account_id=? AND deleted=0').get(id);
console.log('总数:',r.n,'最老:',new Date(r.oldest).toLocaleDateString());
const du=db.prepare('SELECT COUNT(*) as n FROM deleted_uids WHERE account_id=?').get(id);
console.log('deleted_uids:',du.n);
"
```

把结果发给我。

问题很清楚了：

1. `[sync] 939513106@qq.com synced 0` — 同步返回 0，说明 fetchFolder 认为没有新邮件
2. `deleted_uids: 0` — 已清空，不是被过滤
3. `[purge] 删除 3594 封超1年邮件` — **purge 把超1年的邮件删了！** 1/9/2026 之前的都是超1年的（2025年1月之前），所以被删了

**根本原因：purge 的 `oneYearAgo` 计算有误**，`365天前 = 2025-04-11`，所以 2025-04-11 之前的全被删了，但 `ca250226` 最老才到 1/9/2026，说明这个账号的邮件本来就只有这些。

**真正问题是 `synced 0`**：fetchFolder 拉了全量但全部被 `existing` 检查过滤掉了（已存在），所以没有新增。

`ca250226` 账号 QQ 邮箱服务器上有多少封？需要直接连 IMAP 查：

```bash
docker exec iMail node -e "
const Imap=require('imap');
const db=require('better-sqlite3')('/app/data/imall.db');
const acc=db.prepare('SELECT * FROM accounts').all().find(r=>r.id.startsWith('ca250226'));
const cfg=JSON.parse(acc.config);
const imap=new Imap({user:acc.email,password:cfg.credential,host:'imap.qq.com',port:993,tls:true,tlsOptions:{rejectUnauthorized:false},connTimeout:15000});
imap.once('ready',()=>{
  imap.openBox('INBOX',true,(err,box)=>{
    console.log('INBOX 总数:',box?.messages?.total);
    imap.end();
  });
});
imap.once('error',e=>console.log('error:',e.message));
imap.connect();
"
```

服务器有 9646 封，db 只有 415 封。`synced 0` 说明 fetchFolder 拉了但全部被 `existing` 过滤——**不对，415 封不可能覆盖 9646 封**。

真正原因：`fetchFolder` 用的是 `imap.seq.fetch`（序号），但 `existing` 检查用的是 `uid`。序号和 uid 不同，可能导致重复检测失败。

但更可能的是：**`synced 0` 是 autoSync 返回的，autoSync 里 IMAP 走的是 `fetchEmails`，而 `fetchEmails` 内部调 `fetchFolder`，fetchFolder 拉了 9646 封 header，但写入时全部被 `existing` 过滤**。

直接查 db 里这个账号的 uid 范围：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const id=db.prepare('SELECT id FROM accounts').all().find(r=>r.id.startsWith('ca250226')).id;
const rows=db.prepare('SELECT uid FROM emails WHERE account_id=? ORDER BY CAST(uid AS INTEGER) ASC LIMIT 3').all(id);
const rows2=db.prepare('SELECT uid FROM emails WHERE account_id=? ORDER BY CAST(uid AS INTEGER) DESC LIMIT 3').all(id);
console.log('最小uid:',rows.map(r=>r.uid));
console.log('最大uid:',rows2.map(r=>r.uid));
console.log('uid类型:',typeof rows[0]?.uid);
"
```

不需要删 db，但需要清空 deleted_uids（之前清过一次，但 purge 又跑了可能又写入了）：

```bash
docker inspect iMail --format '{{.Created}}' && docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
console.log('deleted_uids:',db.prepare('SELECT COUNT(*) as n FROM deleted_uids').get().n);
console.log('emails:',db.prepare('SELECT COUNT(*) as n FROM emails WHERE deleted=0').get().n);
"
```

先把这个结果发给我，同时确认容器是否更新到最新版本。

进展了！`headerRows:61` 和 `headerRows:670` 说明有新邮件在同步进来。

但 `inbox total:2642 start fetch` 还没有结果，说明还在跑（2642封分批处理中）。

等一会再看：

```bash
docker logs iMail 2>&1 | grep "fetchFolder" | grep "2642\|9646" 
```

同时确认 db 数据是否增加：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const id=db.prepare('SELECT id FROM accounts').all().find(r=>r.id.startsWith('ca250226')).id;
const r=db.prepare('SELECT COUNT(*) as n, MIN(raw_date) as oldest FROM emails WHERE account_id=? AND deleted=0').get(id);
console.log('ca250226 总数:',r.n,'最老:',new Date(r.oldest).toLocaleDateString());
console.log('全部:',db.prepare('SELECT COUNT(*) as n FROM emails WHERE deleted=0').get().n);
"
```

逻辑没问题。你说"不对"是指期望值是多少？近3月应该有 2000+ 封含正文，2066 看起来合理。

还是说"含正文"里包含了一些实际 body 是空字符串但不是 NULL 的情况？直接查一下：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
console.log('body空字符串:',db.prepare(\"SELECT COUNT(*) as n FROM emails WHERE deleted=0 AND body=''\").get().n);
console.log('body NULL:',db.prepare('SELECT COUNT(*) as n FROM emails WHERE deleted=0 AND body IS NULL').get().n);
console.log('body有内容:',db.prepare(\"SELECT COUNT(*) as n FROM emails WHERE deleted=0 AND body!='' AND body IS NOT NULL\").get().n);
"
```

查一下近3月实际有多少封：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const t=Date.now()-90*24*60*60*1000;
console.log('近3月总数:',db.prepare('SELECT COUNT(*) as n FROM emails WHERE deleted=0 AND raw_date>?').get(t).n);
console.log('近3月含正文:',db.prepare(\"SELECT COUNT(*) as n FROM emails WHERE deleted=0 AND raw_date>? AND body!='' AND body IS NOT NULL\").get(t).n);
console.log('超3月含正文:',db.prepare(\"SELECT COUNT(*) as n FROM emails WHERE deleted=0 AND raw_date<=? AND body!='' AND body IS NOT NULL\").get(t).n);
"
```

`fetchBodyByUid` 用 `imap.fetch([parseInt(uid)])` 按 UID fetch，逻辑正确。

问题可能是这些邮件是**今天刚同步进来的重复邮件**，uid 可能是 0 或者无效值。查一下：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const rows=db.prepare(\"SELECT uid,folder,subject,body,raw_date FROM emails WHERE account_id IN (SELECT id FROM accounts WHERE email='824559662@qq.com') AND body='' ORDER BY raw_date DESC LIMIT 5\").all();
rows.forEach(r=>console.log('uid:',r.uid,'folder:',r.folder,'subject:',r.subject.slice(0,20)));
"
```

uid 有效，folder 是 inbox。问题是这些邮件 raw_date 在近3月范围内但 body 为空，说明 SEARCH SINCE 拉到了这些邮件但 body 没有成功写入。

看 `/body` 接口是否正常工作，直接测试一封：

```bash
docker exec iMail node -e "
const {fetchBodyByUid}=require('./src/imap');
const db=require('better-sqlite3')('/app/data/imall.db');
const acc=db.prepare(\"SELECT * FROM accounts WHERE email='824559662@qq.com'\").get();
const cfg=JSON.parse(acc.config);
fetchBodyByUid(acc,cfg,19607,'inbox').then(b=>console.log('body长度:',b?.length,'前50:',b?.slice(0,50))).catch(e=>console.log('error:',e.message));
" 2>&1
```

body 长度 0，说明 IMAP fetch 拿到了邮件但 `parsed.html` 和 `parsed.text` 都是空。这类银行账单邮件可能是纯附件（PDF），正文本来就没有文字内容。

验证一下：

```bash
docker exec iMail node -e "
const {fetchBodyByUid}=require('./src/imap');
const db=require('better-sqlite3')('/app/data/imall.db');
const acc=db.prepare(\"SELECT * FROM accounts WHERE email='824559662@qq.com'\").get();
const cfg=JSON.parse(acc.config);
const Imap=require('imap');
const {simpleParser}=require('mailparser');
const Iconv=require('iconv').Iconv;
const imap=new Imap({user:acc.email,password:cfg.credential,host:'imap.qq.com',port:993,tls:true,tlsOptions:{rejectUnauthorized:false},connTimeout:15000});
imap.once('ready',()=>{
  imap.openBox('INBOX',true,()=>{
    const f=imap.fetch([19607],{bodies:''});
    f.on('message',msg=>{
      msg.on('body',stream=>{
        simpleParser(stream,{Iconv},(err,parsed)=>{
          console.log('html长度:',parsed?.html?.length);
          console.log('text长度:',parsed?.text?.length);
          console.log('attachments:',parsed?.attachments?.map(a=>a.filename));
        });
      });
    });
    f.once('end',()=>imap.end());
  });
});
imap.connect();
" 2>&1</parameter>

